def rounded_avg(n, m):
    """Return the rounded inclusive average in binary, or -1 if n > m."""
    if n > m:
        return -1

    total = n + m
    average, remainder = divmod(total, 2)
    if remainder and average % 2:
        average += 1
    return bin(average)
